def load_settings(raw):
    settings = {}
    timeout = raw.get("timeout")
    if timeout is None:
        timeout = 30
    settings["timeout"] = timeout
    retries = raw.get("retries")
    if retries is None:
        retries = 3
    settings["retries"] = retries
    tags = []
    for t in raw.get("tags", []):
        if t.strip() != "":
            tags.append(t.strip())
    settings["tags"] = tags
    return settings
